            if y == 0:
                return (0, 0)
            elif y == m:
                return (0, m)
    else:
        t_x = (n - x) if v_x > 0 else x
        t_y = (m - y) if v_y > 0 else y

        if t_x * abs(v_y) == t_y * abs(v_x):
            if v_x > 0 and v_y > 0:
                return (n, m)
            elif v_x < 0 and v_y > 0:
                return (0, m)
            elif v_x > 0 and v_y < 0:
                return (n, 0)
            elif v_x < 0 and v_y < 0:
